"use client";

import { useState } from "react";
import Script from "next/script";
import { useRouter, useSearchParams } from "next/navigation";
import { useAuth } from "@/context/AuthContext";

declare global {
  interface Window {
    google: any;
  }
}

export default function AuthPage() {
  const router = useRouter();
  const { login } = useAuth();

  const [mode, setMode] = useState<"login" | "register">("login");

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const searchParams = useSearchParams();
  const redirect = searchParams.get("redirect") || "/";

  async function handleSubmit() {
    setError(null);
    setLoading(true);

    try {
      const endpoint = mode === "login" ? "/auth/login" : "/auth/register";

      const body =
        mode === "login" ? { email, password } : { name, email, password };

      const res = await fetch(`http://localhost:8000${endpoint}`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(body),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.detail || "Authentication failed");
      }

      const data = await res.json();
      await login(data.access_token);
      router.push(redirect);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }

  return (
    <>
      <main className="relative min-h-screen bg-zinc-950 text-zinc-100 overflow-hidden flex items-center justify-center px-6">
        {/* Background Glow */}
        <div className="absolute inset-0">
          <div className="absolute top-[-20%] left-1/2 -translate-x-1/2 w-[900px] h-[900px] bg-white/5 rounded-full blur-[140px]" />
        </div>

        {/* Panel */}
        <div className="relative w-full max-w-md backdrop-blur-2xl bg-zinc-900/40 border border-zinc-800/60 rounded-3xl px-10 py-12 shadow-2xl animate-fadeIn">
          {/* Logo */}
          <div className="mb-10 text-center">
            <h1 className="text-3xl tracking-tight font-medium">WATCHPOP</h1>
            <p className="mt-2 text-sm text-zinc-500">
              Your personal media archive
            </p>
          </div>

          {/* Heading */}
          <div className="space-y-2">
            <h2 className="text-2xl font-medium tracking-tight">
              {mode === "login" ? "Welcome back" : "Create account"}
            </h2>
            <p className="text-sm text-zinc-500">
              {mode === "login"
                ? "Continue your curated journey."
                : "Start building your private collection."}
            </p>
          </div>

          {/* Toggle */}
          <div className="mt-6 flex gap-6 text-sm">
            <button
              onClick={() => setMode("login")}
              className={`transition ${
                mode === "login"
                  ? "text-zinc-100"
                  : "text-zinc-500 hover:text-zinc-300"
              }`}
            >
              Sign in
            </button>

            <button
              onClick={() => setMode("register")}
              className={`transition ${
                mode === "register"
                  ? "text-zinc-100"
                  : "text-zinc-500 hover:text-zinc-300"
              }`}
            >
              Create account
            </button>
          </div>

          {/* Form */}
          <div className="mt-8 space-y-6">
            {mode === "register" && (
              <input
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Name"
                className="w-full bg-transparent border-b border-zinc-800 py-2 text-sm focus:outline-none focus:border-zinc-600 placeholder:text-zinc-600 transition"
              />
            )}

            <input
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="Email"
              className="w-full bg-transparent border-b border-zinc-800 py-2 text-sm focus:outline-none focus:border-zinc-600 placeholder:text-zinc-600 transition"
            />

            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Password"
              className="w-full bg-transparent border-b border-zinc-800 py-2 text-sm focus:outline-none focus:border-zinc-600 placeholder:text-zinc-600 transition"
            />

            {error && <div className="text-sm text-red-400">{error}</div>}

            <button
              onClick={handleSubmit}
              disabled={loading}
              className="w-full mt-4 rounded-xl bg-zinc-800 hover:bg-zinc-700 py-3 text-sm transition disabled:opacity-50"
            >
              {loading
                ? "Please wait…"
                : mode === "login"
                  ? "Sign in"
                  : "Create account"}
            </button>
          </div>

          {/* Divider */}
          <div className="flex items-center gap-4 my-8">
            <div className="h-px flex-1 bg-zinc-800" />
            <span className="text-xs text-zinc-500 tracking-wide">
              OR CONTINUE WITH
            </span>
            <div className="h-px flex-1 bg-zinc-800" />
          </div>

          {/* Google Button Container */}
          <div className="flex justify-center">
            <div id="googleBtn" />
          </div>
        </div>
      </main>

      {/* Google Script */}
      <Script
        src="https://accounts.google.com/gsi/client"
        strategy="afterInteractive"
        onLoad={() => {
          if (!window.google) return;

          window.google.accounts.id.initialize({
            client_id:
              "881288169563-1h7o3ocu33tv8f907720ddh6l3n2d6l1.apps.googleusercontent.com",
            callback: async (response: any) => {
              const res = await fetch("http://localhost:8000/auth/google", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                credentials: "include",
                body: JSON.stringify({
                  token: response.credential,
                }),
              });

              if (!res.ok) return;

              const data = await res.json();
              await login(data.access_token);
              router.push(redirect);
            },
          });

          window.google.accounts.id.renderButton(
            document.getElementById("googleBtn"),
            {
              theme: "filled_black",
              size: "large",
              shape: "pill",
              width: 300,
            },
          );
        }}
      />
    </>
  );
}
